/**
 * The currency registry py-moneyed exposes, paired with the presentation data
 * babel uses for locale en_US.
 *
 * Both tables were recovered by exhaustively probing the reference binary across
 * the whole AAA-ZZZ code space: 308 codes are defined, the rest raise
 * CurrencyDoesNotExist. For a code not listed as an override, en_US renders the
 * ISO code itself as the "symbol" and uses two fraction digits.
 */
import { CurrencyDoesNotExist } from './errors.mjs';

/** Fraction digits used when a currency has no entry in DIGIT_OVERRIDES. */
const DEFAULT_DIGITS = 2;

/** Every currency code py-moneyed defines. */
const CURRENCY_CODES = `
