IEP ILP ILR ILS IMP INR IQD IRR ISJ ISK ITL JMD JOD JPY KES KGS KHR KMF KPW KRH KRO KRW KWD KYD
KZT LAK LBP LKR LRD LSL LTL LTT LUC LUF LUL LVL LVR LYD MAD MAF MCF MDC MDL MGA MGF MKD MKN MLF
MMK MNT MOP MRO MRU MTL MTP MUR MVP MVR MWK MXN MXP MXV MYR MZE MZM MZN NAD NGN NIC NIO NLG NOK
NPR NZD OMR PAB PEI PEN PES PGK PHP PKR PLN PLZ PTE PYG QAR RHD ROL RON RSD RUB RUR RWF SAR SBD
SCR SDD SDG SDP SEK SGD SHP SIT SKK SLE SLL SOS SRD SRG SSP STD STN SUR SVC SYP SZL THB TJR TJS
TMM TMT TND TOP TPE TRL TRY TTD TVD TWD TZS UAH UAK UGS UGX USD USN USS UYI UYP UYU UYW UZS VEB
VED VEF VES VND VNN VUV WST XAF XAG XAU XBA XBB XBC XBD XCD XDR XEU XFO XFU XOF XPD XPF XPT XRE
XSU XTS XUA XXX YDD YER YUD YUM YUN YUR ZAL ZAR ZMK ZMW ZRN ZRZ ZWD ZWL ZWN ZWR
`.trim().split(/\s+/);

/** Codes whose en_US display symbol is not simply the code itself. */
const SYMBOLS = {
  AUD: 'A$',
  BRL: 'R$',
  CAD: 'CA$',
  CNY: 'CN\u00A5',
  EUR: '\u20AC',
  GBP: '\u00A3',
  HKD: 'HK$',
...
  XPF: 0,
  YER: 0,
  ZMK: 0,
  ZWD: 0,
  // 6 currencies with 3 fraction digits
  BHD: 3,
  JOD: 3,
  KWD: 3,
  LYD: 3,
  OMR: 3,
  TND: 3,
  // 2 currencies with 4 fraction digits
  CLF: 4,
  UYW: 4,
};

const REGISTRY = new Map(
  CURRENCY_CODES.map(code => [
    code,
    Object.freeze({
      code,
      symbol: Object.hasOwn(SYMBOLS, code) ? SYMBOLS[code] : code,
      digits: Object.hasOwn(DIGIT_OVERRIDES, code) ? DIGIT_OVERRIDES[code] : DEFAULT_DIGITS,
    }),
  ]),
);

/**
 * Look up a currency by code, upper-casing it first the way py-moneyed does.
 * Throws CurrencyDoesNotExist for anything unregistered.
 */
export function getCurrency(code) {
  const upper = String(code).toUpperCase();
  const currency = REGISTRY.get(upper);
  if (currency === undefined) throw new CurrencyDoesNotExist(upper);
  return currency;
}
